import{_ as t,o,c as a,ao as i}from"./chunks/framework.B1dm7mGt.js";const u=JSON.parse('{"title":"Coupling Limitations","description":"","frontmatter":{},"headers":[],"relativePath":"guides/coupling/limitations.md","filePath":"guides/coupling/limitations.md","lastUpdated":null}'),s={name:"guides/coupling/limitations.md"};function n(r,e,d,l,c,h){return o(),a("div",null,[...e[0]||(e[0]=[i('<h1 id="Coupling-Limitations" tabindex="-1">Coupling Limitations <a class="header-anchor" href="#Coupling-Limitations" aria-label="Permalink to &quot;Coupling Limitations {#Coupling-Limitations}&quot;">​</a></h1><p>Everything on this page is a real constraint of the current implementation. Two of them can produce <strong>silently wrong results</strong> — derivatives through a <code>connect</code> edge, and a model that accumulates into its own <code>du</code> under a contributory <code>share</code> — so read those before building anything serious on either edge kind.</p><h2 id="Derivatives-Through-a-connect-Edge-Are-Wrong" tabindex="-1">Derivatives Through a <code>connect</code> Edge Are Wrong <a class="header-anchor" href="#Derivatives-Through-a-connect-Edge-Are-Wrong" aria-label="Permalink to &quot;Derivatives Through a `connect` Edge Are Wrong {#Derivatives-Through-a-connect-Edge-Are-Wrong}&quot;">​</a></h2><p>This is the sharpest limitation in the package.</p><p><strong>What happens.</strong> Under an implicit solver, ForwardDiff threads dual numbers through the global state vector <code>U</code>. A <code>connect</code> edge has to stage a source state into the receiver&#39;s parameter vector, which holds plain <code>Float64</code>s — storing a dual there would error. The <code>ForwardDiff</code> extension therefore extracts the <em>primal</em> of the dual before writing it, so the connect input is frozen at its current value for the duration of the Newton step.</p><p><strong>Consequence 1 — approximate Jacobian.</strong> The solver still converges to the correct fixed point, because the staged value is refreshed on every evaluation. But the Jacobian it uses omits the coupling term, so it is approximate. For a loosely-coupled system this costs a few extra Newton iterations. For a <em>tightly</em>-coupled stiff <code>connect</code>, convergence can degrade badly.</p><p><strong>Consequence 2 — gradients are incorrect, not merely inaccurate.</strong> Any ForwardDiff derivative taken <em>through</em> a connect edge loses that coupling term entirely. Concretely:</p><ul><li><p>Sensitivity analysis across a <code>connect</code> gives wrong sensitivities.</p></li><li><p>Gradient-based parameter fitting across a <code>connect</code> optimises the wrong objective gradient.</p></li><li><p>The failure is <strong>silent</strong> — no error, no warning, just a number that is not the derivative you asked for.</p></li></ul><p><strong>What to do about it.</strong></p><ul><li><p><a href="./share"><code>share</code></a> is completely unaffected, because it flows through <code>U</code> like any other state. If a coupling can be expressed as a share, and you need derivatives, use a share.</p></li><li><p>If you only need to <em>solve</em>, <code>connect</code> is fine — the trajectory is correct.</p></li><li><p>If you need derivatives through a <code>connect</code>, the standard fix is to route the receiver&#39;s parameter vector through a <code>PreallocationTools.DiffCache</code> so it can hold duals. <strong>This is not built.</strong></p></li></ul><h2 id="Thread-Safety" tabindex="-1">Thread Safety <a class="header-anchor" href="#Thread-Safety" aria-label="Permalink to &quot;Thread Safety {#Thread-Safety}&quot;">​</a></h2><p>A <code>CoupledModel</code> stages <code>connect</code> inputs into a private copy of each receiver, held on the coupled model itself, and resolves any monitor sources into scratch vectors held the same way. That is all mutable scratch, so <strong>one <code>CoupledModel</code> cannot be solved concurrently from several threads</strong> — the trajectories would scribble over each other&#39;s staged inputs.</p><p><code>couple</code> deepcopies each receiver at construction, so building a coupling never mutates the model instances you passed in. The hazard is only in sharing one <code>CoupledModel</code> across threads.</p><p>For a threaded parameter sweep, give each trajectory its own copy:</p><div class="language-julia vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">julia</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">prob_func </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (prob, i, repeat) </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-&gt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> remake</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(prob; f </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> deepcopy</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(coupled))</span></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">solve</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">EnsembleProblem</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(prob; prob_func), </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">Tsit5</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(), </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">EnsembleThreads</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(); trajectories </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 100</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span></code></pre></div><p>Full in-RHS reentrancy — routing connect inputs through the receiver&#39;s per-evaluation <code>p</code> rather than a stored vector — is a tracked follow-up, not a current property.</p><h2 id="A-Contributor&#39;s-Initial-Value-Is-Discarded" tabindex="-1">A Contributor&#39;s Initial Value Is Discarded <a class="header-anchor" href="#A-Contributor&#39;s-Initial-Value-Is-Discarded" aria-label="Permalink to &quot;A Contributor&#39;s Initial Value Is Discarded {#A-Contributor&#39;s-Initial-Value-Is-Discarded}&quot;">​</a></h2><p>Not a limitation of expressiveness — <a href="./share"><code>share(…; op = +)</code></a> sums contributions to a shared derivative, so &quot;one equation per shared state&quot; is no longer a constraint. What survives is smaller and easy to trip over.</p><p>A contributory member supplies a <em>term in the owner&#39;s equation</em>, not a variable of its own. The shared slot&#39;s initial value comes from the <strong>owner</strong>, exactly as under hard-discard, so a contributor&#39;s <code>default_initial_state</code> entry for that state is ignored. If your module&#39;s local initial value for the contributed state matters, it is not a contribution — it is a separate state that should not be shared.</p><h2 id="A-Component-Must-Fully-Write-Its-Own-du" tabindex="-1">A Component Must Fully Write Its Own <code>du</code> <a class="header-anchor" href="#A-Component-Must-Fully-Write-Its-Own-du" aria-label="Permalink to &quot;A Component Must Fully Write Its Own `du` {#A-Component-Must-Fully-Write-Its-Own-du}&quot;">​</a></h2><p>The interface has always expected a component to <em>write</em> every derivative slot it owns rather than accumulate into one. <code>dU</code> arrives from the solver dirty, so a model that does <code>du[i] += …</code> without first assigning <code>du[i]</code> was already reading garbage.</p><p>An accumulating slot sharpens the consequence. Because the coupling adds each member&#39;s write onto a running total, a model that accumulates into its own <code>du</code> sees a <em>plausible partial sum</em> there rather than obvious garbage — so the bug turns into a silent double-count instead of an obvious <code>NaN</code>. Assign first, then modify:</p><div class="language-julia vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">julia</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">du[</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">] </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> f</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(u, p, t)      </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># assign — never `du[1] += ...` as the first write</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">du[</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">] </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> g</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(u, p, t)     </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># fine once the slot is initialised</span></span></code></pre></div><p>CytoZoo deliberately does <strong>not</strong> pre-zero each component&#39;s block to paper over this: it would repair a broken model on its shared states while leaving its private states broken, and add writes to the hot path.</p><h2 id="Derived-Sources-Must-Be-Declared,-and-Cost-the-Whole-Monitor-Vector" tabindex="-1">Derived Sources Must Be Declared, and Cost the Whole Monitor Vector <a class="header-anchor" href="#Derived-Sources-Must-Be-Declared,-and-Cost-the-Whole-Monitor-Vector" aria-label="Permalink to &quot;Derived Sources Must Be Declared, and Cost the Whole Monitor Vector {#Derived-Sources-Must-Be-Declared,-and-Cost-the-Whole-Monitor-Vector}&quot;">​</a></h2><p>A <code>connect</code> source may name a state or a monitor, so a derived quantity such as <code>ADP = C_A - ATP</code> is wirable (see <a href="./connect">Connect Edges</a>). Three constraints come with it.</p><p><strong>The source model must declare the observable.</strong> A derived quantity that no model exposes through <a href="/CytoZoo.jl/previews/PR49/reference/api#CytoZoo.monitor_names"><code>monitor_names</code></a> cannot be wired. For a model you own this is a one-line addition; for a third-party model it means wrapping it in an adapter, the same pattern <code>ext/ThunderboltExt.jl</code> uses.</p><p><strong>Wiring one monitor computes them all.</strong> <a href="/CytoZoo.jl/previews/PR49/reference/api#CytoZoo.monitor_values!"><code>monitor_values!</code></a> fills a model&#39;s entire monitor vector, once per evaluation per sourcing component. A model with a handful of monitors costs nothing measurable; a model with hundreds pays for all of them to deliver one. Splitting that into per-monitor access is a possible future addition, not a current property.</p><p><strong>A monitor source may receive a <code>connect</code> edge, but monitor edges must not form a cycle.</strong> The pre-pass stages each monitor-sourcing component&#39;s inputs immediately before evaluating its monitors, walking those components in dependency order, so a monitor that reads a staged slot sees the current evaluation&#39;s value. That makes a <em>feedthrough</em> exact — <code>A</code>&#39;s state drives <code>B</code>, and <code>B</code>&#39;s monitor feeds back into <code>A</code>, all within one evaluation.</p><p>What <code>couple</code> rejects is a <em>cycle</em>: monitor edges that order a component before itself. The check is at <strong>component</strong> granularity, because <code>monitor_values!</code> fills a model&#39;s whole monitor vector in one call and which monitor reads which staged slot is not knowable statically. So two components whose monitors feed each other are rejected even if the individual monitors involved would not actually have read the contested slots — conservative, and the error names the edges that form the cycle.</p><p>Two caveats on that exactness. The ordering is exact in <strong>value</strong>, not in the Jacobian: a feedthrough is still a <code>connect</code>, so under an implicit solver both legs are frozen to their primal and the coupling contributes nothing to Newton&#39;s Jacobian (see the first section of this page). And the guarantee stops at the component boundary — a <strong>nested <code>CoupledModel</code></strong> that sources a monitor and carries <code>connect</code> edges of its own still lags by one evaluation, because its inner components are staged by its own walk, which runs after the outer pre-pass has already asked it for its monitors. <code>couple</code> does not currently detect that case.</p><h2 id="Other-Constraints" tabindex="-1">Other Constraints <a class="header-anchor" href="#Other-Constraints" aria-label="Permalink to &quot;Other Constraints {#Other-Constraints}&quot;">​</a></h2><p><strong>No DAE or algebraic-constraint coupling.</strong> Every component must be an ODE. Coupling that introduces an algebraic constraint between components is out of scope.</p><p><strong>Nested coupling is supported but lightly exercised.</strong> <code>CoupledModel &lt;: AbstractCardiacCellModel</code>, so a coupling can be a component of another coupling, and the layout logic collapses accordingly. It has not been validated against a demanding real use case.</p><p><strong>Composition is construction-time only.</strong> Structure is fixed when <code>couple</code> returns. Nothing about the graph can change during a solve, and nothing routes through <code>p</code>.</p><p><strong>GPU execution is not shipped.</strong> The design keeps structs isbits-friendly, but no coupled model has been run or tested on a device.</p><h2 id="Summary" tabindex="-1">Summary <a class="header-anchor" href="#Summary" aria-label="Permalink to &quot;Summary {#Summary}&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:right;">Limitation</th><th style="text-align:right;">Severity</th><th style="text-align:right;">Affects</th></tr></thead><tbody><tr><td style="text-align:right;">Derivatives through <code>connect</code> are wrong</td><td style="text-align:right;"><strong>silent incorrectness</strong></td><td style="text-align:right;"><code>connect</code> only</td></tr><tr><td style="text-align:right;">Newton convergence with tight stiff <code>connect</code></td><td style="text-align:right;">performance</td><td style="text-align:right;"><code>connect</code> only</td></tr><tr><td style="text-align:right;">One <code>CoupledModel</code> is not thread-safe</td><td style="text-align:right;">crash / corruption</td><td style="text-align:right;"><code>connect</code> receivers</td></tr><tr><td style="text-align:right;">A contributor&#39;s initial value is discarded</td><td style="text-align:right;">correctness trap</td><td style="text-align:right;"><code>share(…; op = +)</code></td></tr><tr><td style="text-align:right;">A model that accumulates into its own <code>du</code> double-counts</td><td style="text-align:right;"><strong>silent incorrectness</strong></td><td style="text-align:right;"><code>share(…; op = +)</code></td></tr><tr><td style="text-align:right;">A derived source costs its model&#39;s whole monitor vector</td><td style="text-align:right;">performance</td><td style="text-align:right;"><code>connect</code></td></tr><tr><td style="text-align:right;">Monitor-edge cycles rejected conservatively (component granularity)</td><td style="text-align:right;">build-time rejection</td><td style="text-align:right;"><code>connect</code></td></tr><tr><td style="text-align:right;">No DAE coupling</td><td style="text-align:right;">scope</td><td style="text-align:right;">all</td></tr></tbody></table><h2 id="See-Also" tabindex="-1">See Also <a class="header-anchor" href="#See-Also" aria-label="Permalink to &quot;See Also {#See-Also}&quot;">​</a></h2><ul><li><p><a href="./../../reference/design">Design Notes</a> — why the architecture is shaped this way.</p></li><li><p><a href="./../../reference/internals">Coupling Internals</a> — the mechanism behind these constraints.</p></li></ul>',40)])])}const g=t(s,[["render",n]]);export{u as __pageData,g as default};
